with open('review.md') as f:
    content = f.read()
lines = content.split('\n')
# check last char
print('Last char:', repr(content[-1]))
# check no blank lines before keys
for i, line in enumerate(lines):
    if line.startswith('KEY'):
        if i > 0 and lines[i-1].strip() == '':
            print('Blank line before key at', i)
        break
# check key lines
key_lines = [l for l in lines if l.startswith('KEY')]
print('Num key lines:', len(key_lines))
for l in key_lines:
    if l.endswith('.'):
        print('Period in key line:', l)
    if '  ' in l:
        print('Double space in key line:', l)
    if l != l.strip():
        print('Indent in key line:', repr(l))
    if '<' in l or '>' in l or '\"' in l or \"'\" in l:
        print('Bad chars in key line:', l)
print('Done')
